//! Composition (design: Layers): which entries apply to some agents in one place, in what order, and where
//! each output line comes from. Harness-neutral: adapters (adapters.rs) decide where the text goes.

use crate::model::{Audience, Entry, Kind, Scope, Visibility};
use crate::stack::Stacks;
use serde::Serialize;
use std::collections::BTreeSet;
use std::path::PathBuf;

pub const BEGIN: &str = "<!-- lords-command:begin -->";
pub const END: &str = "<!-- lords-command:end -->";
const HEADER: &str =
    "<!-- Generated by Lords Command from its stacks; change an entry there, then sync. -->";

const MEMORY_INTRO: &str = "Notes agents wrote down earlier. Read a note's file when its topic comes up; notes are not rules.";

/// The line that stands for notes meant for one role, when the reader's role is unknown: how many per role, and
/// the dirs they are in.
fn role_pointer(notes: &[&Entry]) -> Option<String> {
    if notes.is_empty() {
        return None;
    }
    let mut counts: std::collections::BTreeMap<&str, usize> = std::collections::BTreeMap::new();
    let mut dirs: Vec<String> = Vec::new();
    for e in notes {
        for r in &e.meta.roles {
            *counts.entry(r.as_str()).or_default() += 1;
        }
        let dir =
            e.body_file.parent().map(|d| d.to_string_lossy().into_owned()).unwrap_or_default();
        let dir = if cfg!(windows) { dir.replace('/', "\\") } else { dir };
        if !dirs.contains(&dir) {
            dirs.push(dir);
        }
    }
    let counts: Vec<String> = counts.iter().map(|(r, n)| format!("{r}: {n}")).collect();
    let dirs: Vec<String> = dirs.iter().map(|d| format!("`{d}`")).collect();
    Some(format!(
        "- More notes are for one role only ({}); in that role, find them in {} (each file's `roles` says whose).",
        counts.join(", "),
        dirs.join(", ")
    ))
}

/// One memory index line: name, its one-line hook, and the file to read.
pub fn index_line(e: &Entry) -> String {
    let name =
        e.meta.name.clone().unwrap_or_else(|| e.id().trim_start_matches("memory.").to_string());
    let hook = e.meta.description.as_deref().unwrap_or(&e.meta.title);
    let path = e.body_file.to_string_lossy().into_owned();
    let path = if cfg!(windows) { path.replace('/', "\\") } else { path };
    if hook.trim().is_empty() || hook == name {
        format!("- {name} (`{path}`)")
    } else {
        format!("- {name}: {hook} (`{path}`)")
    }
}

/// Kinds composed into instruction text, in section order.
const SECTIONS: [(Kind, &str); 5] = [
    (Kind::Intent, "Owner intent"),
    (Kind::Role, "Roles"),
    (Kind::Rule, "Rules"),
    (Kind::Fact, "Facts"),
    (Kind::Status, "Status"),
];

/// Which layers a composition takes.
#[derive(Clone, Debug)]
pub enum Layers {
    /// User-level files, which every run on the machine reads (product turns too, backbone requirement BB-5): only global entries
    /// for every role, and no memory. See `user_level`.
    Global,
    /// A repo's own files: its project, the repo, path entries covering `sub`, and the global entries the user
    /// level leaves out (role-specific ones and memory). With `global`, every global entry (a file that must
    /// stand alone: a tracked AGENTS.md, a role file a brief points to).
    Repo { repo: String, project: Option<String>, sub: Option<String>, global: bool },
    /// A working dir with no git repo (e.g. a harness dir): like a repo, with its own workspace layer.
    Workspace { name: String, project: Option<String>, global: bool },
}

/// Whether an entry suits every run on the machine, so it may go to user-level files: a global entry for every
/// role (no `roles`) that is no memory note. Skills install user-level as before.
pub fn user_level(e: &Entry) -> bool {
    matches!(e.scope, Scope::Global)
        && (e.meta.kind == Kind::Skill || (e.meta.roles.is_empty() && e.meta.kind != Kind::Memory))
}

#[derive(Clone, Debug)]
pub struct Context {
    pub audience: Vec<Audience>,
    pub layers: Layers,
    /// Only entries from the public stack (a tracked file anyone can read).
    pub public_only: bool,
    /// Memory stores the target's harness already loads by itself: left out of the memory index.
    pub skip_stores: Vec<String>,
    /// The role whoever reads the file has (`None`: unknown). A known role gets only entries for it (or for
    /// every role); with an unknown one, role-specific entries are labelled, and role-specific notes are left out
    /// of the memory index for a pointer to them.
    pub roles: Option<Vec<String>>,
}

#[derive(Clone, Debug, Serialize)]
pub struct Source {
    /// 1-based line in the composed text.
    pub line: usize,
    pub id: String,
    pub stack: Visibility,
    pub file: PathBuf,
    pub file_line: usize,
}

#[derive(Clone, Debug, Default)]
pub struct Composed {
    /// The block, markers included; empty when nothing applies.
    pub text: String,
    pub sources: Vec<Source>,
    /// Ids composed, in order.
    pub ids: Vec<String>,
    /// Ids dropped because an applicable entry overrides them.
    pub overridden: Vec<String>,
    /// Applicable skills (installed as links, not composed into text).
    pub skills: Vec<String>,
}

fn in_layers(e: &Entry, layers: &Layers) -> bool {
    match (layers, &e.scope) {
        (Layers::Global, _) => user_level(e),
        (Layers::Workspace { project, .. }, Scope::Project(p)) => project.as_deref() == Some(p),
        (Layers::Workspace { name, .. }, Scope::Workspace(w)) => w == name,
        (Layers::Workspace { global, .. }, Scope::Global) => *global || !user_level(e),
        (Layers::Workspace { .. }, _) => false,
        (Layers::Repo { project, .. }, Scope::Project(p)) => project.as_deref() == Some(p),
        (Layers::Repo { repo, .. }, Scope::Repo(r)) => r == repo,
        (Layers::Repo { repo, sub, .. }, Scope::Path { repo: r, sub: s }) => {
            r == repo
                && sub
                    .as_deref()
                    .is_some_and(|here| here == s || here.starts_with(&format!("{s}/")))
        }
        (Layers::Repo { global, .. }, Scope::Global) => *global || !user_level(e),
        (Layers::Repo { .. }, Scope::Workspace(_)) => false,
    }
}

fn reaches(e: &Entry, audience: &[Audience]) -> bool {
    e.meta.audience.contains(&Audience::All) || e.meta.audience.iter().any(|a| audience.contains(a))
}

/// The label for an entry meant for only some of a target's audiences (Sol and Astra share one file).
/// The label for an entry meant for only some of a file's readers: the agents (Sol and Astra share one file)
/// and, where the file's role is unknown, the roles.
/// The role that product runs have (backbone requirement BB-4). Place files never reach product runs (BB-5), so an entry for every
/// other role needs no role label there.
pub const PRODUCT_ROLE: &str = "product";

fn only_for(e: &Entry, ctx: &Context, development: &[String]) -> Option<String> {
    let mut parts = Vec::new();
    if let Some(agents) = only_agents(e, &ctx.audience) {
        parts.push(agents);
    }
    let every_development_role =
        !development.is_empty() && development.iter().all(|r| e.meta.roles.contains(r));
    if ctx.roles.is_none() && !e.meta.roles.is_empty() && !every_development_role {
        parts.push(e.meta.roles.join(", "));
    }
    (!parts.is_empty()).then(|| parts.join("; "))
}

fn only_agents(e: &Entry, audience: &[Audience]) -> Option<String> {
    if e.meta.audience.contains(&Audience::All)
        || audience.iter().all(|a| e.meta.audience.contains(a))
    {
        return None;
    }
    let names: Vec<&str> = e
        .meta
        .audience
        .iter()
        .filter(|a| audience.contains(a))
        .map(|a| match a {
            Audience::Opus => "Opus",
            Audience::Sol => "Sol",
            Audience::Astra => "Astra",
            Audience::All => "all",
        })
        .collect();
    Some(names.join(", "))
}

pub fn applicable<'a>(stacks: &'a Stacks, ctx: &Context) -> Vec<&'a Entry> {
    stacks
        .entries()
        .filter(|e| e.active())
        .filter(|e| !ctx.public_only || e.stack == Visibility::Public)
        .filter(|e| in_layers(e, &ctx.layers) && reaches(e, &ctx.audience))
        .filter(|e| for_role(e, ctx))
        .collect()
}

/// A known role takes entries for it or for every role; an unknown one keeps them all (labelled, or pointed to).
fn for_role(e: &Entry, ctx: &Context) -> bool {
    match &ctx.roles {
        None => true,
        Some(roles) => e.meta.roles.is_empty() || e.meta.roles.iter().any(|r| roles.contains(r)),
    }
}

pub fn compose(stacks: &Stacks, ctx: &Context) -> Composed {
    let mut development: Vec<String> = stacks
        .all()
        .flat_map(|s| s.manifest.roles.iter())
        .filter(|r| *r != PRODUCT_ROLE)
        .cloned()
        .collect();
    development.sort();
    development.dedup();
    let all = applicable(stacks, ctx);
    let overridden: BTreeSet<&str> =
        all.iter().flat_map(|e| e.meta.overrides.iter().map(String::as_str)).collect();
    let live: Vec<&Entry> = all.into_iter().filter(|e| !overridden.contains(e.id())).collect();
    let mut out = Composed {
        overridden: overridden.iter().map(|s| s.to_string()).collect(),
        skills: live
            .iter()
            .filter(|e| e.meta.kind == Kind::Skill)
            .map(|e| e.id().to_string())
            .collect(),
        ..Composed::default()
    };
    let ids: BTreeSet<&str> = live.iter().map(|e| e.id()).collect();
    fn extension_of<'e>(e: &'e Entry, ids: &BTreeSet<&str>) -> Option<&'e str> {
        e.meta.extends.first().map(String::as_str).filter(|t| ids.contains(t))
    }

    let mut lines: Vec<String> = Vec::new();
    let push_entry = |e: &Entry, lines: &mut Vec<String>, out: &mut Composed| {
        if let Some(who) = only_for(e, ctx, &development) {
            lines.push(format!("({who} only)"));
        }
        for (i, l) in e.body.trim_matches('\n').lines().enumerate() {
            lines.push(l.trim_end_matches('\r').to_string());
            out.sources.push(Source {
                line: lines.len(),
                id: e.id().to_string(),
                stack: e.stack,
                file: e.body_file.clone(),
                file_line: e.body_line + i,
            });
        }
        out.ids.push(e.id().to_string());
    };

    for (kind, heading) in SECTIONS {
        let mut section: Vec<&Entry> = live
            .iter()
            .copied()
            .filter(|e| e.meta.kind == kind && extension_of(e, &ids).is_none())
            .collect();
        if section.is_empty() {
            continue;
        }
        section.sort_by(|a, b| {
            (a.rank(), a.meta.order.unwrap_or(0), a.id()).cmp(&(
                b.rank(),
                b.meta.order.unwrap_or(0),
                b.id(),
            ))
        });
        if !lines.is_empty() {
            lines.push(String::new());
        }
        lines.push(format!("# {heading}"));
        for e in section {
            lines.push(String::new());
            push_entry(e, &mut lines, &mut out);
            // Extensions follow the entry they extend, in id order.
            let mut ext: Vec<&Entry> =
                live.iter().copied().filter(|x| extension_of(x, &ids) == Some(e.id())).collect();
            ext.sort_by_key(|x| x.id().to_string());
            for x in ext {
                push_entry(x, &mut lines, &mut out);
            }
        }
    }
    // Skills tracked in this repo: listed where they are (backbone requirement BB-8), so every harness can find them.
    let here: Vec<&Entry> = live
        .iter()
        .copied()
        .filter(|e| {
            e.meta.kind == Kind::Skill
                && matches!(e.meta.origin, crate::model::Origin::InRepo { .. })
        })
        .collect();
    if !here.is_empty() {
        if !lines.is_empty() {
            lines.push(String::new());
        }
        lines.push("# Skills in this repo".into());
        lines.push(String::new());
        for e in here {
            lines.push(index_line(e));
            out.sources.push(Source {
                line: lines.len(),
                id: e.id().to_string(),
                stack: e.stack,
                file: e.body_file.clone(),
                file_line: 1,
            });
            out.ids.push(e.id().to_string());
        }
    }
    // Memory: an index, not text. Each harness reads the notes on demand (docs/load-order.md); a note binds
    // nobody until it is promoted to an intent, rule or fact.
    let mut notes: Vec<&Entry> = live
        .iter()
        .copied()
        .filter(|e| e.meta.kind == Kind::Memory)
        .filter(|e| match &e.meta.origin {
            crate::model::Origin::Imported { store, .. } => !ctx.skip_stores.contains(store),
            _ => true,
        })
        .collect();
    notes.sort_by(|a, b| (a.rank(), a.id()).cmp(&(b.rank(), b.id())));
    // Where the reader's role is unknown, notes for one role stay out of the index; one line says where they are.
    let (role_notes, notes): (Vec<&Entry>, Vec<&Entry>) =
        notes.into_iter().partition(|e| ctx.roles.is_none() && !e.meta.roles.is_empty());
    let pointer = role_pointer(&role_notes);
    if !notes.is_empty() || pointer.is_some() {
        if !lines.is_empty() {
            lines.push(String::new());
        }
        lines.push("# Memory".into());
        lines.push(String::new());
        lines.push(MEMORY_INTRO.into());
        lines.push(String::new());
        for e in notes {
            lines.push(index_line(e));
            out.sources.push(Source {
                line: lines.len(),
                id: e.id().to_string(),
                stack: e.stack,
                file: e.body_file.clone(),
                file_line: 1,
            });
            out.ids.push(e.id().to_string());
        }
        if let Some(p) = pointer {
            lines.push(p);
        }
    }
    if out.ids.is_empty() && lines.is_empty() {
        return out;
    }
    // Two header lines precede the composed lines.
    for s in out.sources.iter_mut() {
        s.line += 2;
    }
    let mut text = format!("{BEGIN}\n{HEADER}\n");
    text.push_str(&lines.join("\n"));
    text.push('\n');
    text.push_str(END);
    text.push('\n');
    out.text = text;
    out
}

/// A managed block holding `body` (e.g. one include line).
pub fn block(body: &str) -> String {
    format!("{BEGIN}\n{HEADER}\n{}\n{END}\n", body.trim_end())
}

/// A composed block with `pre` first, right after the header (a repo file's tracked-instructions line).
pub fn with_preamble(text: &str, pre: &str) -> String {
    let head = format!("{BEGIN}\n{HEADER}\n");
    match text.strip_prefix(&head) {
        Some(rest) => format!("{head}{}\n\n{rest}", pre.trim_end()),
        None => format!("{}\n\n{text}", pre.trim_end()),
    }
}

/// Puts a block into a file's text: between existing markers, else appended. `replace` drops the text outside.
pub fn place_block(current: &str, block: &str, replace: bool) -> String {
    if replace {
        return block.to_string();
    }
    if let (Some(b), Some(e)) = (current.find(BEGIN), current.find(END)) {
        if b < e {
            let after = &current[e + END.len()..];
            let after =
                after.strip_prefix("\r\n").or_else(|| after.strip_prefix('\n')).unwrap_or(after);
            return format!("{}{block}{after}", &current[..b]);
        }
    }
    if block.is_empty() || current.is_empty() {
        return format!("{current}{block}");
    }
    let sep = if current.ends_with("\n\n") {
        ""
    } else if current.ends_with('\n') {
        "\n"
    } else {
        "\n\n"
    };
    format!("{current}{sep}{block}")
}

/// The managed block currently in a file, if any.
pub fn current_block(text: &str) -> Option<&str> {
    let b = text.find(BEGIN)?;
    let e = text[b..].find(END)? + b + END.len();
    let e = if text[e..].starts_with('\n') { e + 1 } else { e };
    Some(&text[b..e])
}
